<?php $id = get_the_ID(); $terms = get_the_terms( $id, 'igp_category' ); $term = ! is_wp_error( $terms ) && $terms ? $terms[0] : null; $image = igp_product_image( $id ); ?>
<article class="product-card"><a href="<?php the_permalink(); ?>" class="product-image" aria-label="<?php echo esc_attr( 'View ' . get_the_title() ); ?>"><?php if ( $image ) : ?><img src="<?php echo esc_url( $image ); ?>" alt="<?php echo esc_attr( get_the_title() . ' generator part' ); ?>" loading="lazy"><?php else : ?><span class="product-image-fallback" aria-hidden="true">IGP</span><?php endif; ?></a><div class="product-card-body"><p class="eyebrow"><?php echo esc_html( $term ? $term->name : '' ); ?></p><h3><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h3><p><?php echo esc_html( get_the_excerpt() ); ?></p><div class="card-actions"><a href="<?php the_permalink(); ?>">View details <span aria-hidden="true">→</span></a><a class="whatsapp-link" target="_blank" rel="noopener noreferrer" href="<?php echo esc_url( igp_whatsapp( get_the_title(), get_permalink() ) ); ?>" aria-label="<?php echo esc_attr( 'Ask about ' . get_the_title() . ' on WhatsApp' ); ?>"><?php echo igp_icon(); ?> WhatsApp</a></div></div></article>
